mapper.select:
SELECT FROM role_permissions WHERE deleted_at IS NULL AND role_code IN
#{roleCode}
ORDER BY id

mapper.update:
UPDATE role_permissions SET deleted_at=(CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version=version+1,
    update_user_id=#{et.updateUserId}, update_time=#{et.updateTime}
WHERE id=#{et.id} AND tenant_id=#{et.tenantId} AND deleted_at IS NULL AND version=#{MP_OPTLOCK_VERSION_ORIGINAL}
